<?php $title = $property['titulo']; $phone = preg_replace('/\D+/', '', (string) $property['telefone_contato']); $message = rawurlencode('Olá! Encontrei seu imóvel no LarPerto e tenho interesse: ' . $property['titulo']); $mainImage = $images[0]['arquivo'] ?? null; ?>
<section class="container detail"><div class="gallery"><div class="gallery-main"><?php if ($mainImage): ?><img src="<?= Helper::e(Helper::url('assets/uploads/imoveis/' . rawurlencode($mainImage))) ?>" alt="<?= Helper::e($property['titulo']) ?>"><?php else: ?>LarPerto<?php endif; ?></div><?php if (count($images) > 1): ?><div class="gallery-thumbs"><?php foreach ($images as $image): ?><img src="<?= Helper::e(Helper::url('assets/uploads/imoveis/' . rawurlencode($image['arquivo']))) ?>" alt="Foto do imóvel"><?php endforeach; ?></div><?php endif; ?></div><div class="detail-content"><span class="tag"><?= Helper::e(ucfirst($property['finalidade'])) ?></span><h1><?= Helper::e($property['titulo']) ?></h1><p class="muted"><?= Helper::e($property['bairro']) ?>, <?= Helper::e($property['cidade']) ?>-GO</p><strong class="price large"><?= Helper::e(Helper::formatPrice($property['preco'])) ?><?= $property['finalidade'] === 'aluguel' ? ' / mês' : '' ?></strong><div class="feature-list"><span><?= (int) $property['quartos'] ?> quartos</span><span><?= (int) $property['banheiros'] ?> banheiros</span><span><?= (int) $property['vagas'] ?> vagas</span><span><?= Helper::e($property['area_construida'] ?: '-') ?> m²</span></div><h2>Sobre o imóvel</h2><p><?= nl2br(Helper::e($property['descricao'])) ?></p><?php if ($phone): ?><a class="button whatsapp" target="_blank" rel="noopener" href="https://wa.me/<?= Helper::e($phone) ?>?text=<?= $message ?>">Conversar pelo WhatsApp</a><?php endif; ?><p class="muted">Anunciado por <?= Helper::e($property['anunciante']) ?></p></div></section>